(()=>{const S=__SB,P=S.P,K=S.KEYS;const res=[];
 const clear=()=>{for(const e of S.E)S.scene.remove(e.rig.root);S.E.length=0;if(S.TOK)S.TOK.clear();};
 for(const n of [1,3]){let tot=0,dmg=0,wins=0;const T=20;
  for(let trial=0;trial<T;trial++){clear();S.tp(-48,20);P.hp=P.maxHp=5000;P.dead=false;P.act=null;P.lock=null;P.st=P.maxSt;
   const foes=[];for(let i=0;i<n;i++){const e=S.spawnEnemy('goblin',P.pos.x-3+i*3,P.pos.z-9,{});e.aggro=true;e.alertT=0;e.state='combat';foes.push(e);}
   let f=0;for(;f<60*40;f++){const alive=foes.filter(e=>!e.dead);if(!alive.length)break;let b=null,bd=1e9;for(const e of alive){const d=Math.hypot(e.pos.x-P.pos.x,e.pos.z-P.pos.z);if(d<bd){bd=d;b=e;}}
     S.CAM.yaw=Math.atan2(-(b.pos.x-P.pos.x),-(b.pos.z-P.pos.z));if(bd>2.1){K.KeyW=true;}else{K.KeyW=false;if(f%6===0)S.IN.atkP=true;}S.sim(1);}
   K.KeyW=false;tot+=f;dmg+=5000-P.hp;if(f<60*40)wins++;}
  res.push(n+' goblin'+(n>1?'s':'')+': '+(tot/T/60).toFixed(2)+'s avg, dmg taken '+(dmg/T).toFixed(0)+' ('+wins+'/'+T+' cleared)');}
 return res.join(' || ');})()
